package cn.iocoder.yudao.module.pms.asset.service.license;
import cn.iocoder.yudao.module.pms.asset.api.migration.DppmsLicenseRecordApi.Envelope;
import org.junit.jupiter.api.Test;
import java.util.Base64;
import static org.junit.jupiter.api.Assertions.*;

class DeviceLicenseRecordCipherTest {
    static final String KEY="AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=";
    // Independently generated by the source-side PyCryptodome adapter in the initial-capture namespace.
    static final Envelope ORIGINAL=new Envelope("201","wKTXfkCmKjfA2QkZplMJhlpHxPy0HcFrHcKVnUmiOoHKjL/kreTKVkKr1ro=","TEST-V1","ec22604ee3b747037c94d0a09d93bd5a46d823428c8c4c99dd5c32db15db58dc");
    final DeviceLicenseRecordCipher cipher=new DeviceLicenseRecordCipher(KEY,"TEST-V1");
    @Test void independentUnicodeEnvelopeAndStoredVersionAuthenticateWithoutExposingPlaintext() {
        assertEquals(ORIGINAL.codeMac(),cipher.verify(ORIGINAL,1L));
        String sealed=cipher.seal(ORIGINAL,1L);
        assertTrue(sealed.contains("AES-256-GCM"));assertTrue(sealed.contains("TEST-V1"));
        assertFalse(sealed.contains("合成许可"));assertEquals(ORIGINAL.codeMac(),cipher.verifyStored(sealed,1L));
    }
    @Test void wrongTenantSourceOrKeyIdCannotBeSubstituted() {
        assertThrows(IllegalArgumentException.class,()->cipher.verify(ORIGINAL,2L));
        assertThrows(IllegalArgumentException.class,()->cipher.verify(new Envelope("202",ORIGINAL.ciphertext(),ORIGINAL.keyId(),ORIGINAL.codeMac()),1L));
        assertThrows(IllegalArgumentException.class,()->cipher.verify(new Envelope("201",ORIGINAL.ciphertext(),"OTHER",ORIGINAL.codeMac()),1L));
    }
    @Test void tamperedCipherAndMacFailWithNoSensitiveCause() {
        byte[] bytes=Base64.getDecoder().decode(ORIGINAL.ciphertext());bytes[bytes.length-1]^=1;
        var error=assertThrows(IllegalArgumentException.class,()->cipher.verify(new Envelope("201",Base64.getEncoder().encodeToString(bytes),ORIGINAL.keyId(),ORIGINAL.codeMac()),1L));
        assertEquals("LICENSE_ENVELOPE_AUTHENTICATION_FAILED",error.getMessage());assertNull(error.getCause());
        assertThrows(IllegalArgumentException.class,()->cipher.verify(new Envelope("201",ORIGINAL.ciphertext(),ORIGINAL.keyId(),"0".repeat(64)),1L));
        assertThrows(IllegalArgumentException.class,()->cipher.verifyStored("{}",1L));
    }
    @Test void missingAndInvalidKeysFailClosed() {
        assertThrows(IllegalArgumentException.class,()->new DeviceLicenseRecordCipher("","TEST-V1").verify(ORIGINAL,1L));
        assertThrows(IllegalArgumentException.class,()->new DeviceLicenseRecordCipher(Base64.getEncoder().encodeToString(new byte[16]),"TEST-V1"));
    }
}
